	MOVQ dst_base+0(FP), AX
	MOVQ lits_len+32(FP), SI
	MOVQ offset+48(FP), CX
	MOVQ length+56(FP), DX
	CMPL DX, $0x0b

	// emitCopy2WithLits
	XORQ    DI, DI
	SUBL    $0x40, CX
	LEAL    -11(DX), R8
	LEAL    -4(DX), DX
	MOVW    CX, 1(AX)
	CMPL    DX, $0x07
	CMOVLGE R8, DI
