	ADDQ  SI, AX
	TESTL DI, DI
	JZ    standalone_emitcopy2_lits_done

	// emitRepeat
	CMPL DI, $0x1d
	JBE  repeat_one_standalone_emitcopy2_lits
	LEAL -30(DI), CX
	CMPL DI, $0x0000011e
	JB   repeat_two_standalone_emitcopy2_lits
