// func simdExecAVX2(dst *byte, lits *byte, tok *byte, ll *byte, offc *byte, raw *byte, esc *byte, n int, st *[4]int)
// Requires: AVX, AVX2, BMI2, CMOV
TEXT ·simdExecAVX2(SB), NOSPLIT, $8-72
	MOVQ    dst+0(FP), AX
	MOVQ    lits+8(FP), CX
	MOVQ    tok+16(FP), DX
	MOVQ    ll+24(FP), BX
	MOVQ    offc+32(FP), SI
	MOVQ    raw+40(FP), DI
	MOVQ    n+56(FP), R8
	ADDQ    DX, R8
	MOVQ    st+64(FP), R9
	MOVQ    (R9), R10
	ADDQ    8(R9), CX
	MOVQ    16(R9), R9
	XORQ    R11, R11
	CMPQ    DX, R8
	JAE     simdExecAVX2_done
	PCALIGN $0x20

simdExecAVX2_loop:
	MOVBQZX (DX), R12
	VMOVDQU (CX), Y0
	VMOVDQU Y0, (AX)(R10*1)
	MOVBQZX (BX), R13
	MOVQ    R12, R14
	SHRQ    $0x01, R14
	ANDQ    $0x01, R14
	ADDQ    R14, BX
	NEGQ    R14
	ANDQ    R14, R13
	CMPQ    R13, $0x21
	JE      simdExecAVX2_litlong

simdExecAVX2_litback:
	ADDQ    R13, R10
	ADDQ    R13, CX
	MOVBQZX (SI), R13
	LEAQ    ·simdOffTab+0(SB), R14
	MOVL    (R14)(R13*4), R13
	MOVQ    R12, R14
	ANDQ    $0x01, R14
	XORQ    $0x01, R14
	ADDQ    R14, SI
	MOVQ    R11, R15
	SHRQ    $0x03, R15
	MOVQ    (DI)(R15*1), R15
	MOVQ    R11, BP
	ANDQ    $0x07, BP
	SHRXQ   BP, R15, R15
	MOVL    R13, BP
	SHRL    $0x18, BP
	BZHIQ   BP, R15, R15
	ANDL    $0x00ffffff, R13
	ADDQ    R15, R13
	NEGQ    R14
	ANDQ    R14, BP
	ADDQ    BP, R11
	TESTQ   R14, R14
	CMOVQNE R13, R9
	MOVQ    R9, R13
	CMPQ    R13, R10
	CMOVQHI R10, R13
	MOVQ    R10, R14
	SUBQ    R13, R14
	SHRQ    $0x02, R12
	CMPQ    R13, R12
	JB      simdExecAVX2_pattern
	VMOVDQU (AX)(R14*1), Y0
	VMOVDQU Y0, (AX)(R10*1)

simdExecAVX2_check:
	CMPQ R12, $0x21
	JE   simdExecAVX2_long

simdExecAVX2_next:
	ADDQ R12, R10
	INCQ DX
	CMPQ DX, R8
	JB   simdExecAVX2_loop

simdExecAVX2_done:
	VZEROUPPER
	MOVQ st+64(FP), AX
	MOVQ R10, (AX)
	MOVQ lits+8(FP), DX
	SUBQ DX, CX
	MOVQ CX, 8(AX)
	MOVQ R9, 16(AX)
	RET

simdExecAVX2_pattern:
	LEAQ           simdPatternTab<>+0(SB), R15
	SHLQ           $0x05, R13
	VMOVDQU        (AX)(R14*1), Y0
	VBROADCASTI128 (AX)(R14*1), Y1
	VMOVDQU        (R15)(R13*1), Y2
	VPSHUFB        Y2, Y1, Y1
	VPBLENDVB      Y2, Y0, Y1, Y0
	VMOVDQU        Y0, (AX)(R10*1)
	JMP            simdExecAVX2_check

simdExecAVX2_litlong:
	MOVQ    esc+48(FP), R13
	MOVBQZX (R13), R14
	INCQ    R13
	MOVQ    R13, esc+48(FP)
	LEAQ    33(R14), R13
	ADDQ    $0x20, R14
	SHRQ    $0x05, R14
	LEAQ    32(CX), R15
	LEAQ    32(R10), BP

simdExecAVX2_litloop:
	VMOVDQU (R15), Y0
	VMOVDQU Y0, (AX)(BP*1)
	ADDQ    $0x20, R15
	ADDQ    $0x20, BP
	DECQ    R14
	JNZ     simdExecAVX2_litloop
	JMP     simdExecAVX2_litback

simdExecAVX2_long:
	MOVQ R10, R12
	SUBQ R14, R12
	CMPQ R12, $0x20
	JAE  simdExecAVX2_longok
	MOVQ st+64(FP), R12
	MOVQ $0x00000001, 24(R12)

simdExecAVX2_longok:
	MOVQ    esc+48(FP), R12
	MOVBQZX (R12), R13
	INCQ    R12
	MOVQ    R12, esc+48(FP)
	LEAQ    33(R13), R12
	ADDQ    $0x20, R13
	SHRQ    $0x05, R13
	LEAQ    32(R14), R14
	LEAQ    32(R10), R15

simdExecAVX2_longloop:
	VMOVDQU (AX)(R14*1), Y0
	VMOVDQU Y0, (AX)(R15*1)
	ADDQ    $0x20, R14
	ADDQ    $0x20, R15
	DECQ    R13
	JNZ     simdExecAVX2_longloop
	JMP     simdExecAVX2_next

