// func simdTokStatsAVX2(b *byte, n int) (out int, lit int, rep int, esc int, ok bool)
// Requires: AVX, AVX2, SSE2
TEXT ·simdTokStatsAVX2(SB), NOSPLIT, $0-49
	MOVQ         b+0(FP), AX
	MOVQ         n+8(FP), CX
	ADDQ         AX, CX
	VPXOR        Y0, Y0, Y0
	VPCMPEQB     Y1, Y1, Y1
	VPXOR        Y2, Y2, Y2
	VPXOR        Y3, Y3, Y3
	VPXOR        Y4, Y4, Y4
	VPXOR        Y5, Y5, Y5
	MOVL         $0x0000003f, DX
	VMOVD        DX, X6
	VPBROADCASTB X6, Y6
	MOVL         $0x00000004, DX
	VMOVD        DX, X7
	VPBROADCASTB X7, Y7
	MOVL         $0x00000002, DX
	VMOVD        DX, X8
	VPBROADCASTB X8, Y8
	MOVL         $0x00000001, DX
	VMOVD        DX, X9
	VPBROADCASTB X9, Y9
	MOVL         $0x00000087, DX
	VMOVD        DX, X10
	VPBROADCASTB X10, Y10

simdTokStatsAVX2_loop:
	VMOVDQU      (AX), Y11
	VPMINUB      Y10, Y11, Y12
	VPCMPEQB     Y11, Y12, Y12
	VPAND        Y12, Y1, Y1
	VPSRLW       $0x02, Y11, Y12
	VPAND        Y6, Y12, Y12
	VPSADBW      Y0, Y12, Y12
	VPADDQ       Y12, Y2, Y2
	VPAND        Y8, Y11, Y12
	VPSADBW      Y0, Y12, Y12
	VPADDQ       Y12, Y3, Y3
	VPAND        Y9, Y11, Y12
	VPSADBW      Y0, Y12, Y12
	VPADDQ       Y12, Y4, Y4
	VPSRLW       $0x05, Y11, Y12
	VPAND        Y11, Y12, Y12
	VPAND        Y7, Y12, Y12
	VPSADBW      Y0, Y12, Y12
	VPADDQ       Y12, Y5, Y5
	ADDQ         $0x20, AX
	CMPQ         AX, CX
	JB           simdTokStatsAVX2_loop
	VPMOVMSKB    Y1, AX
	CMPL         AX, $0xffffffff
	SETEQ        AL
	MOVB         AL, ok+48(FP)
	VEXTRACTI128 $0x01, Y2, X0
	VPADDQ       X0, X2, X0
	VPSHUFD      $0x4e, X0, X1
	VPADDQ       X1, X0, X0
	MOVQ         X0, AX
	MOVQ         AX, out+16(FP)
	VEXTRACTI128 $0x01, Y3, X0
	VPADDQ       X0, X3, X0
	VPSHUFD      $0x4e, X0, X1
	VPADDQ       X1, X0, X0
	MOVQ         X0, AX
	MOVQ         AX, lit+24(FP)
	VEXTRACTI128 $0x01, Y4, X0
	VPADDQ       X0, X4, X0
	VPSHUFD      $0x4e, X0, X1
	VPADDQ       X1, X0, X0
	MOVQ         X0, AX
	MOVQ         AX, rep+32(FP)
	VEXTRACTI128 $0x01, Y5, X0
	VPADDQ       X0, X5, X0
	VPSHUFD      $0x4e, X0, X1
	VPADDQ       X1, X0, X0
	MOVQ         X0, AX
	MOVQ         AX, esc+40(FP)
	VZEROUPPER
	RET

